import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # 1. Apply each distinct event (by batch_seq) only once.
    events = events.drop_duplicates(subset=["batch_seq"])

    # Build lookup of target rows by key.
    target_map = {}
    for _, row in target.iterrows():
        key = (row["account_id"], row["symbol"])
        target_map[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"],
        }

    # Start new_positions as a copy of the target rows; will be mutated/removed
    # as events are applied.
    new_positions = {key: dict(val) for key, val in target_map.items()}
    closed_positions = {}

    if len(events) > 0:
        events_sorted = events.sort_values(
            ["account_id", "symbol", "row_version", "batch_seq"],
            kind="mergesort",
        )
    else:
        events_sorted = events

    if len(events_sorted) > 0:
        grouped = events_sorted.groupby(["account_id", "symbol"], sort=False)
    else:
        grouped = []

    for key, grp in grouped:
        target_row = target_map.get(key)
        guard_version = target_row["row_version"] if target_row is not None else None

        current_state = dict(target_row) if target_row is not None else None
        last_effective_event = None
        last_effective_was_removal = False

        for _, ev in grp.iterrows():
            rv = ev["row_version"]

            # 2. Replay guard.
            if guard_version is not None and rv <= guard_version:
                continue

            op = ev["op"]
            qty = ev["qty"]
            price = ev["price"]

            is_close = (op == "D") or (op in ("I", "U") and qty == 0)

            if is_close:
                if current_state is not None:
                    current_state = None
                    last_effective_event = rv
                    last_effective_was_removal = True
                # else: does nothing, no change to last effective event
            else:
                if current_state is not None:
                    if op == "U":
                        if pd.notna(price):
                            new_price = price
                        else:
                            new_price = current_state["price"]
                    else:  # 'I'
                        new_price = price
                    current_state = {
                        "qty": qty,
                        "price": new_price,
                        "row_version": rv,
                    }
                else:
                    current_state = {
                        "qty": qty,
                        "price": price,
                        "row_version": rv,
                    }
                last_effective_event = rv
                last_effective_was_removal = False

        if current_state is None:
            if key in new_positions:
                del new_positions[key]
            if last_effective_was_removal:
                closed_positions[key] = last_effective_event
        else:
            new_positions[key] = current_state

    rows = []
    for (account_id, symbol), val in new_positions.items():
        rows.append(
            {
                "account_id": account_id,
                "symbol": symbol,
                "qty": int(val["qty"]),
                "price": val["price"] if pd.notna(val["price"]) else np.nan,
                "row_version": int(val["row_version"]),
            }
        )
    new_positions_df = pd.DataFrame(
        rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )
    if len(new_positions_df) > 0:
        new_positions_df["account_id"] = new_positions_df["account_id"].astype("int64")
        new_positions_df["qty"] = new_positions_df["qty"].astype("int64")
        new_positions_df["price"] = new_positions_df["price"].astype("float64")
        new_positions_df["row_version"] = new_positions_df["row_version"].astype("int64")

    rows2 = []
    for (account_id, symbol), closed_version in closed_positions.items():
        rows2.append(
            {
                "account_id": account_id,
                "symbol": symbol,
                "closed_version": int(closed_version),
            }
        )
    closed_positions_df = pd.DataFrame(
        rows2, columns=["account_id", "symbol", "closed_version"]
    )
    if len(closed_positions_df) > 0:
        closed_positions_df["account_id"] = closed_positions_df["account_id"].astype("int64")
        closed_positions_df["closed_version"] = closed_positions_df["closed_version"].astype("int64")

    return {"new_positions": new_positions_df, "closed_positions": closed_positions_df}
